function setup(){return '<div class="setup"><section class="story"><div><div class="brand"><span class="mark">C</span><span>Cashflow<small>For freelancers & small businesses</small></span></div><span class="eyebrow" style="color:#b4d3bc">Make uneven income easier to plan</span><h1>Know what your cash can cover next.</h1><p>See your current balance against known bills and expected client income. Add history when you are ready; unclear statement rows stay in review.</p></div><p>Your ledger is encrypted on this device. Keep your recovery key somewhere separate and safe.</p></section><section class="setupbox"><div class="setupcard"><span class="eyebrow">Start in under a minute</span><h2>Get a useful cash picture.</h2><p>Enter one balance and any near-term money in or bills due. You can skip estimates and refine them later.</p><form data-form="setup"><div class="formgrid"><div class="field"><label>Your name</label><input name="name" required placeholder="e.g. Ada"></div><div class="field"><label>Which best describes you?</label><select name="segment"><option value="freelancer">Freelancer or independent professional</option><option value="small-business">Small-business owner</option><option value="personal">Managing personal money</option></select></div><div class="field"><label>First account or wallet</label><input name="account" required placeholder="Opay, Moniepoint, PalmPay..."></div><div class="field"><label>Current balance (NGN)</label><input name="balance" type="number" min="0" value="0" required></div><div class="field"><label>Expected money in (optional)</label><input name="inName" placeholder="Client payment, salary..."></div><div class="field"><label>Expected amount (NGN)</label><input name="inAmount" type="number" min="0" value="0"></div><div class="field"><label>Expected date</label><input name="inDate" type="date"></div><div class="field"><label>Known bill or commitment (optional)</label><input name="billName" placeholder="Rent, data, supplier..."></div><div class="field"><label>Amount due (NGN)</label><input name="billAmount" type="number" min="0" value="0"></div><div class="field"><label>Due date</label><input name="billDate" type="date"></div></div><div class="notice">Your entries are encrypted and saved in this browser only. No login, bank connection, or cloud backup. Statement imports never change your manually entered account balance.</div><button class="btn primary" style="margin-top:10px;width:100%">See my cash picture</button></form><div class="sample">Look around first? <button data-action="demo">Load clearly labelled sample</button></div></div></section></div>';}
function accounts(){if(!D().accounts.length)return '<div class="inline-empty">Add an account to see combined cash.</div>';return D().accounts.map(a=>{let im=D().imports.filter(i=>i.account===a.id).sort((x,y)=>y.end.localeCompare(x.end))[0];return '<div class="row"><span class="avatar">'+esc(a.name[0].toUpperCase())+'</span><span class="rowmain"><b>'+esc(a.name)+'</b><small>Balance as of '+date(a.asof)+' · '+(im?"history through "+date(im.end):"no history imported")+'</small></span><b class="amount">'+money(a.balance)+'</b><button class="btn small" data-action="editaccount" data-id="'+a.id+'">Edit</button></div>';}).join("");}
function latest(){return D().imports.filter(i=>i.end).slice().sort((a,b)=>b.end.localeCompare(a.end))[0];}
function health(){let i=latest();if(!i)return '<section class="card health warn"><span class="symbol">!</span><div><h3>Balances are ready; history is not imported</h3><p>Plan from balances now. Import statement later; duplicates are skipped and unclear rows go to review.</p><button class="btn small" data-action="import">Import statement</button></div></section>';let age=Math.max(0,Math.floor((new Date(iso()+"T12:00")-new Date(i.end+"T12:00"))/86400000)),missing=D().accounts.filter(a=>!D().imports.some(x=>x.account===a.id)).length,stale=age>=45;return '<section class="card health '+(stale||missing?"warn":"")+'"><span class="symbol">'+(stale||missing?"!":"✓")+'</span><div><h3>'+(stale?"History may be behind":"Recent statement history imported")+'</h3><p>Latest dated row: '+date(i.end)+' ('+age+' days ago) in '+esc(i.file)+'. '+(missing?missing+" account(s) have no history yet. ":"")+'Late backfills are welcome; exact duplicates are skipped.</p><button class="btn small" data-action="import">Import / catch up</button></div></section>';}
function monthTotals(){let m=iso().slice(0,7);return D().tx.filter(t=>t.date.slice(0,7)===m&&t.status==="confirmed").reduce((s,t)=>{if(t.type==="income")s.i+=num(t.amount);if(t.type==="expense")s.o+=num(t.amount);return s;},{i:0,o:0});}
function chart(){let a=[];for(let i=5;i>=0;i--){let d=new Date();d.setDate(1);d.setMonth(d.getMonth()-i);a.push({k:d.getFullYear()+"-"+String(d.getMonth()+1).padStart(2,"0"),l:new Intl.DateTimeFormat("en",{month:"short"}).format(d),i:0,o:0});}D().tx.forEach(t=>{let m=a.find(x=>x.k===t.date.slice(0,7));if(m&&t.status==="confirmed"){if(t.type==="income")m.i+=num(t.amount);if(t.type==="expense")m.o+=num(t.amount);}});let max=Math.max(1,...a.map(x=>Math.max(x.i,x.o)));return '<div class="bars">'+a.map(x=>'<div class="month"><div class="pair"><i class="bar" style="height:'+Math.max(3,x.i/max*90)+'%"></i><i class="bar out" style="height:'+Math.max(3,x.o/max*90)+'%"></i></div><small>'+x.l+'</small></div>').join("")+'</div><div class="legend"><span><i></i>In</span><span><i class="out"></i>Out</span></div>';}
function catOpts(v){return opts(cats,v)}function typeOpts(v){return opts(["expense","income","saving","transfer"],v)}function purposeOpts(v){let allowed=state.profile.mixed?purposes:biz()?["Business","Owner draw","Transfer","Needs sorting"]:["Personal","Transfer","Needs sorting"];if(v&&!allowed.includes(v))allowed=[v,...allowed];return opts(allowed,v)}
function txrow(t){let purpose=t.purpose||(t.type==="transfer"?"Transfer":biz()?"Business":"Personal"),purposeLabel=state.profile.mixed&&t.purposeSource==="workspace-default"?purpose+" (default)":purpose,st=t.status==="review"?'<i class="pill">Review</i>':'<i class="pill ok">'+esc(t.cat)+"</i>";return '<details><summary class="row"><span class="avatar">'+(t.type==="income"?"↑":t.type==="transfer"?"↔":"↓")+'</span><span class="rowmain"><b>'+esc(t.desc)+'</b><small>'+date(t.date)+' · '+esc(acct(t.account)?.name||"Account")+' · '+esc(purposeLabel)+' · '+st+'</small></span><b class="amount '+(t.type==="income"?"income":"")+'">'+(t.type==="income"?"+":t.type==="expense"?"−":"")+money(t.amount)+'</b></summary><div class="edit"><small>'+Math.round((t.conf||0)*100)+'% match</small><select data-cat="'+t.id+'">'+catOpts(t.cat)+'</select><select data-type="'+t.id+'">'+typeOpts(t.type)+'</select><select data-purpose="'+t.id+'">'+purposeOpts(purpose)+'</select><button class="btn small '+(t.status==="review"?"primary":"")+'" data-action="savecat" data-id="'+t.id+'">'+(t.status==="review"?"Save & learn":"Save")+'</button></div></details>';}
function home(){let m=monthTotals(),g=mainGoal(),recent=D().tx.slice().sort((a,b)=>b.date.localeCompare(a.date)).slice(0,5),up=D().plans.filter(p=>within(p.date,14)).sort((a,b)=>a.date.localeCompare(b.date)),receivable=biz()?D().invoices.filter(i=>i.status==="sent"&&within(i.due,30)).reduce((s,i)=>s+num(i.amount),0):0;let goal=g?'<div class="sect"><div><h3>'+esc(g.name)+'</h3><p>'+goalMoney(g,g.saved)+' of '+goalMoney(g,g.target)+'</p></div><button class="btn small" data-action="contrib-add" data-id="'+g.id+'">Add contribution</button></div><div class="progress"><span style="width:'+Math.min(100,g.target?g.saved/g.target*100:0)+'%"></span></div><div class="foot"><span>'+Math.round(g.target?g.saved/g.target*100:0)+'% complete</span><span>'+date(g.due)+'</span></div>':'<div class="empty"><b>Give cash a direction</b><p>Keep one priority visible alongside cashflow.</p><button class="btn primary" data-action="goal">Add goal</button></div>';return heading("Good "+(new Date().getHours()<12?"morning":new Date().getHours()<17?"afternoon":"evening")+", "+esc((state.profile.name||"there").split(" ")[0]),biz()?"See client money, operating costs and obligations together.":"Balances, plans and activity in one place.",'<button class="btn primary" data-action="log">+ Log money</button>')+'<div class="grid two"><section class="card hero"><small>'+(state.profile.mixed?"Balances across all accounts":biz()?"Cash in reach":"Available after known bills")+'</small><strong class="big">'+money(safe())+'</strong><p>Current balances less known bills due in 30 days. Expected income stays separate; mixed-use balances combine all accounts.</p><div class="hero-stats"><div><span>'+D().accounts.length+' accounts</span><b>'+money(bal())+'</b></div><div><span>Expected income (30 days)</span><b>'+money(cashIn()+receivable)+'</b></div></div><button class="btn hero-btn" data-action="editaccount" data-id="'+(D().accounts[0]?.id||"")+'">Update balances</button></section>'+health()+'</div><div class="grid three" style="margin-top:12px"><div class="card metric"><small>In this month</small><strong>'+money(m.i)+'</strong><em>Confirmed rows only</em></div><div class="card metric"><small>Out this month</small><strong>'+money(m.o)+'</strong><em>Transfers excluded</em></div><div class="card metric"><small>'+(biz()?"Unpaid invoices":"Goal progress")+'</small><strong>'+(biz()?money(D().invoices.filter(i=>i.status==="sent").reduce((s,i)=>s+num(i.amount),0)):g?Math.round(g.target?g.saved/g.target*100:0)+"%":"—")+'</strong><em>'+(biz()?"Receivables are not cash":"One priority at a time")+'</em></div></div><div class="grid two" style="margin-top:12px"><section class="card pad"><div class="sect"><div><h2>Accounts</h2><p>Balances you last checked</p></div><button class="btn small" data-action="account">+ Account</button></div><div class="rows">'+accounts()+'</div></section><section class="card trend"><div class="sect"><div><h2>Cashflow trend</h2><p>Confirmed history</p></div></div>'+chart()+'</section></div><div class="grid two" style="margin-top:12px"><section class="card pad"><div class="sect"><div><h2>Recent activity</h2><p>'+pending()+' item(s) need review</p></div><button class="btn small" data-view="activity">View all</button></div><div class="rows">'+(recent.map(txrow).join("")||'<div class="inline-empty">Import a statement or log money.</div>')+'</div></section><section class="card pad"><div class="sect"><div><h2>'+(biz()?"Next cash events":"Your next steps")+'</h2><p>Planned through two weeks</p></div><button class="btn small" data-action="flow">+ Plan</button></div><div class="rows">'+(up.map(p=>'<div class="row"><span class="avatar">'+(p.type==="income"?"↑":"↓")+'</span><span class="rowmain"><b>'+esc(p.name)+'</b><small>'+date(p.date)+' · '+p.type+'</small></span><b class="amount">'+money(p.amount)+'</b></div>').join("")||'<div class="inline-empty">Add expected income and bills.</div>')+'</div><div class="card pad" style="margin-top:10px">'+goal+'</div></section></div>';}
function activity(){let q=search.toLowerCase(),defaults=state.profile.mixed?D().tx.filter(t=>t.purposeSource==="workspace-default").length:0,rows=D().tx.slice().sort((a,b)=>b.date.localeCompare(a.date)).filter(t=>(filter==="all"||(filter==="purpose-default"?t.purposeSource==="workspace-default":t.status===filter))&&(!q||(t.desc+" "+t.cat+" "+(t.purpose||"")).toLowerCase().includes(q))),clear=D().tx.filter(t=>t.status==="review"&&t.cat!=="Needs sorting"&&t.type!=="transfer").length,lastBatch=latestImport(),undos=undoImports();return heading(filter==="review"?"Review":"Activity","Import once. Correct a merchant once; matching transactions learn from you.",'<button class="btn primary" data-action="import">Import statement</button>')+(importBusy?'<div class="review import-progress" role="status"><span class="spinner" aria-hidden="true"></span><span><b>Importing statement…</b><small>Reading rows and preparing them for review.</small></span></div>':"")+(filter==="review"&&!pending()?'<div class="notice">You’re all caught up. New uncertain transactions will appear here for review.</div>':"")+(undos.length?'<section class="review import-undo"><b>Undo any of your last 3 imports</b>'+undoImportRows()+'</section>':lastBatch?'<div class="review import-undo"><span class="import-undo-copy"><b>Last import: '+esc(lastBatch.file||"statement")+'</b><small>Undo is unavailable for this older import.</small></span></div>':"")+(defaults?'<div class="review"><b>'+defaults+' transactions use the default purpose</b><p>In mixed mode, these start with the main view. Correct exceptions; matching merchants can reuse your feedback.</p><button class="btn primary small" data-action="review-purpose-defaults">Review assumed purposes</button></div>':"")+(pending()&&filter!=="review"?'<div class="review"><b>'+pending()+' rows need a look</b><p>Confirm clear suggestions in one tap or correct a merchant and apply it to matching rows.</p><button class="btn primary small" data-action="accept">Confirm '+clear+' clear suggestions</button></div>':"")+'<section class="card pad"><div class="toolbar"><input data-search type="search" placeholder="Search activity" value="'+esc(search)+'"><select data-filter><option value="all" '+(filter==="all"?"selected":"")+'>All</option><option value="review" '+(filter==="review"?"selected":"")+' >Needs review</option><option value="confirmed" '+(filter==="confirmed"?"selected":"")+' >Confirmed</option>'+(defaults?'<option value="purpose-default" '+(filter==="purpose-default"?"selected":"")+' >Purpose assumed ('+defaults+')</option>':"")+'</select></div><div class="rows">'+(rows.map(txrow).join("")||'<div class="empty"><b>No matching activity</b><p>Import an XLSX, CSV, or text PDF statement to start sorting.</p></div>')+'</div></section>';}
function goalCard(g,primary){let pct=Math.min(100,Math.round(g.target?num(g.saved)/num(g.target)*100:0));return '<section class="card goal '+(primary?"featured-goal":"")+'"><div class="sect"><div><span class="eyebrow">'+(primary?"MAIN GOAL":"Supporting goal")+'</span><h2>'+esc(g.name)+'</h2><small>'+(g.due?"Deadline: "+date(g.due):"No deadline set")+'</small></div><button class="btn small" data-action="editgoal" data-id="'+g.id+'">Edit goal</button></div><p>'+goalMoney(g,g.saved)+' of '+goalMoney(g,g.target)+' - '+pct+'%</p>'+goalPath(g,primary)+'<div class="goal-actions">'+(primary?"":'<button class="btn small" data-action="main-goal" data-id="'+g.id+'">Make main</button>')+'<button class="btn primary small" data-action="contrib-add" data-id="'+g.id+'" '+(num(g.saved)>=num(g.target)?"disabled":"")+' aria-label="Add a contribution to '+esc(g.name)+'">+ Add</button><button class="btn small" data-action="contrib-subtract" data-id="'+g.id+'" '+(num(g.saved)<=0?"disabled":"")+' aria-label="Subtract a contribution from '+esc(g.name)+'">- Subtract</button><button class="btn small danger" data-action="delgoal" data-id="'+g.id+'">Delete goal</button></div></section>';}
function goals(){normalizeGoals();let a=D().goals,g=mainGoal(),cta=a.length>=3?'<span class="pill ok">3 of 3 goals</span>':'<button class="btn primary" data-action="goal">+ Add goal</button>',body=g?goalCard(g,true)+a.filter(x=>x.id!==g.id).map(x=>goalCard(x,false)).join(""):'<section class="card pad empty"><b>Give your money a direction</b><p>Choose one priority. You can add up to two supporting goals and see the main goal move through its checkpoints.</p><button class="btn primary" data-action="goal">Set my first goal</button></section>';return heading("Goals","Choose one main goal and up to two supporting goals. Set 3-6 checkpoints; contribution timing is optional.",cta)+body;}
function invoices(){let open=D().invoices.filter(i=>i.status==="sent"),out=open.reduce((s,i)=>s+num(i.amount),0),late=open.filter(i=>i.due<iso()).reduce((s,i)=>s+num(i.amount),0);return heading("Invoices","Receivables are expected money, not available cash.",'<button class="btn primary" data-action="invoice">+ Add invoice</button>')+'<div class="grid three"><div class="card metric"><small>Outstanding</small><strong>'+money(out)+'</strong></div><div class="card metric"><small>Overdue</small><strong>'+money(late)+'</strong></div><div class="card metric"><small>Marked paid</small><strong>'+money(D().invoices.filter(i=>i.status==="paid").reduce((s,i)=>s+num(i.amount),0))+'</strong></div></div><section class="card pad" style="margin-top:12px"><div class="sect"><div><h2>Receivables</h2><p>Mark paid when client settles.</p></div></div>'+(D().invoices.map(i=>'<div class="invoice"><span><b>'+esc(i.client)+'</b><small>'+esc(i.ref||"Invoice")+'</small></span><b>'+money(i.amount)+'</b><span class="invdate">'+date(i.due)+'</span><i class="pill '+(i.status==="paid"?"ok":i.due<iso()?"red":"")+' invstatus">'+(i.status==="paid"?"Paid":i.due<iso()?"Overdue":"Sent")+'</i>'+(i.status==="sent"?'<button class="btn small" data-action="paid" data-id="'+i.id+'">Mark paid</button>':"<span></span>")+'</div>').join("")||'<div class="inline-empty">No invoices yet.</div>')+'</section><div class="notice" style="margin-top:10px">Marking paid does not create a bank transaction or change account balances.</div>';}
function ask(q){let daily=D().tx.filter(t=>t.status==="confirmed"&&t.type==="expense"&&t.date>=shift(-30)&&(!state.profile.mixed||t.purpose==="Business"||t.purpose==="Owner draw")).reduce((s,t)=>s+num(t.amount),0),days=daily>0?bal()/(daily/30):NaN;return window.CashCoach.answer(q,{transactions:D().tx,accounts:D().accounts,goals:D().goals,plans:D().plans,imports:D().imports,invoices:D().invoices,mode:state.profile.mode,mixed:!!state.profile.mixed,today:iso(),balance:bal(),safeToSpend:safe(),accountCount:D().accounts.length,runwayDays:days});}
function followups(q){if(/goal|saving|target|checkpoint/i.test(q))return[["How many goals do I have?","How many goals do I have?"],["What is left on my main goal?","How much is left on my main goal?"],["What is my next checkpoint?","What is my next goal checkpoint?"]];if(/account|balance|wallet/i.test(q))return[["How many accounts do I have?","How many accounts do I have?"],["How much can I safely spend?","How much can I safely spend?"],["Why did imports not update my balance?","Why did importing not update my balance?"]];if(/income|bill|cashflow|invoice/i.test(q))return[["What bills are coming up?","What bills are coming up?"],["What expected income is coming?","What expected income is coming in the next 30 days?"],["How much did I spend this month?","How much did I spend this month?"]];if(!q)return[["How many goals do I have?","How many goals do I have?"],["What can you do?","What can you do?"],["What needs sorting?","What needs sorting?"]];return[["What needs sorting?","What needs sorting?"],["What did I spend most on?","What did I spend most on?"],["How up to date is my history?","How up to date is my transaction history?"]];}
function coach(){let last=[...coachThread].reverse().find(m=>m.role==="user")?.text||"",messages=coachThread.map(m=>'<div class="chat-message '+(m.role==="user"?"user":"assistant")+'"><small>'+(m.role==="user"?"You":"Cash Coach")+'</small><div class="bubble">'+esc(state.profile.hideBalances&&m.role==="assistant"?m.text.replace(/\b(?:NGN|USD)\s+[\d,]+(?:\.\d+)?/g,"*****"):m.text)+'</div></div>').join(""),suggestions=followups(last).map(([label,q])=>'<button class="chip" type="button" data-q="'+esc(q)+'">'+esc(label)+'</button>').join("");if(!messages)messages='<div class="chat-message assistant"><small>Cash Coach</small><div class="bubble">Ask me about balances, spending, income, sorting, runway or your goals. I will answer from the information saved in this ledger.</div></div>';return heading("Cash Coach","Ask a question about your cashflow. Replies use local calculations and the data in this ledger.",'<button class="btn small" data-action="clear-coach">Clear chat</button>')+'<section class="chat-shell" aria-label="Cash Coach conversation"><div class="chat-log" aria-live="polite">'+messages+'</div><div class="chat-suggestions"><small>Try asking</small>'+suggestions+'</div><div class="coach-note">If statement history is missing or old, the Coach will flag that its answer may be incomplete. It cannot answer every kind of financial question.</div><form data-form="coach" class="chat-form"><textarea name="question" rows="2" maxlength="500" required aria-label="Ask Cash Coach" placeholder="e.g. How much did I spend this month?"></textarea><button class="btn primary" type="submit">Send</button></form></section>';}
function settings(){return heading("Settings","Balances are manual. Keep a backup and use a private device.","")+'<section class="card pad workspace-settings"><div class="sect"><div><h2>Primary view</h2><p>All accounts and activity stay in one ledger. Choose Personal or Business as your main view. If you mix spending, enable purpose sorting below.</p></div></div><div class="actions"><button class="btn small '+(!biz()?"primary":"")+'" data-action="personal">Use Personal view</button><button class="btn small '+(biz()?"primary":"")+'" data-action="business">Use Business view</button></div><label class="mix-setting"><input id="mixedPurposes" type="checkbox" '+(state.profile.mixed?"checked":"")+'><span><b>Track mixed personal and business use</b><small>Correct a merchant purpose once to reuse it on matching records.</small></span></label></section><div class="grid two"><section class="card pad"><div class="sect"><div><h2>Accounts</h2><p>Current balances you entered</p></div><button class="btn small" data-action="account">+ Account</button></div><div class="rows">'+accounts()+'</div></section><section class="card pad"><div class="sect"><div><h2>Planned cashflow</h2><p>Expected income and bills</p></div><button class="btn small" data-action="flow">+ Add</button></div>'+(D().plans.map(p=>'<div class="row"><span class="rowmain"><b>'+esc(p.name)+' · '+money(p.amount)+'</b><small>'+p.type+' · '+date(p.date)+'</small></span><button class="btn small" data-action="editplan" data-id="'+p.id+'">Edit</button><button class="btn small" data-action="delplan" data-id="'+p.id+'">Remove</button></div>').join("")||'<div class="inline-empty">No upcoming items.</div>')+'</section></div><section class="card pad" style="margin-top:12px"><div class="sect"><div><h2>Data and privacy</h2><p>Encrypted in browser storage; no login or cloud sync.</p></div></div><div class="notice warn">Encryption is local to this device and depends on your password and recovery key. Keep the recovery key separate. Use synthetic or anonymized records; this remains a prototype.</div><div class="settingsrow"><div><b>Change password</b><small>Requires your recovery key; the current password will be replaced.</small></div><button class="btn small" data-action="use-recovery">Change password</button></div><div class="settingsrow"><div><b>Replace recovery key</b><small>The old key stays active until you confirm and save the new key.</small></div><button class="btn small" data-action="rotate-recovery">Replace key</button></div><div class="settingsrow"><div><b>Download encrypted JSON backup</b><small>Encrypted data only. The password or recovery key is needed to restore it.</small></div><button class="btn small" data-action="backup">Download</button></div><div class="settingsrow"><div><b>Restore backup</b></div><button class="btn small" data-action="restore">Choose file</button></div><div class="settingsrow"><div><b>Export this ledger CSV</b><small>CSV exports are not encrypted.</small></div><button class="btn small" data-action="csv">Export</button></div><div class="settingsrow"><div><b>Clear pilot data from this browser</b></div><button class="btn danger small" data-action="reset">Clear</button></div></section><section class="card pad" style="margin-top:12px"><div class="sect"><div><h2>Import ranges</h2><p>Dated rows, not guaranteed continuous coverage.</p></div></div>'+(D().imports.map(i=>i.status&&i.status!=="imported"?'<div class="row"><span class="rowmain"><b>'+esc(i.file)+' · '+esc(i.status)+'</b><small>'+esc(i.reason||"No transactions imported")+'</small></span></div>':'<div class="row"><span class="rowmain"><b>'+esc(acct(i.account)?.name||"Account")+' · '+date(i.start)+' to '+date(i.end)+'</b><small>'+i.added+' added · '+i.dups+' duplicates skipped'+(i.statementSummary?(i.statementSummary.reconciles===true?' · statement totals verified':i.statementSummary.reconciles===false?' · statement totals need review':''):'')+'</small></span></div>').join("")||'<div class="inline-empty">No statements imported yet.</div>')+'</section>';}
function page(){return view==="activity"?activity():view==="goals"?goals():view==="coach"?coach():view==="invoices"&&biz()?invoices():view==="settings"?settings():home();}
function feedbackWidget(){return '<details class="feedback-widget"><summary class="feedback-trigger">Feedback</summary><section class="feedback-panel" aria-labelledby="feedback-title"><h2 id="feedback-title">YOUR FEEDBACK MATTERS</h2><p>Tell me what’s working or what needs fixing.</p><a class="feedback-contact feedback-whatsapp" href="https://wa.me/2348085318908?text=Hi%2C%20I%E2%80%99d%20like%20to%20share%20feedback%20about%20Cashflow%20Pilot." target="_blank" rel="noopener noreferrer">Message on WhatsApp</a><a class="feedback-contact feedback-email" href="mailto:dominiqueglobal24@gmail.com?subject=Cashflow%20Pilot%20feedback">Send an email</a></section></details>';}
function render(){let th=state.profile.theme==="dark"?"dark":"light";document.documentElement.dataset.theme=th;document.querySelector('meta[name="theme-color"]')?.setAttribute("content",th==="dark"?"#101713":"#f5f6f2");if(vaultMode!=="open"){app.innerHTML=vaultGate()+feedbackWidget();return;}if(!state.profile.ready){app.innerHTML=setup()+feedbackWidget();return;}if(view==="invoices"&&!biz())view="home";app.innerHTML=shell(page()+modalHtml())+feedbackWidget();let log=app.querySelector(".chat-log");if(log)log.scrollTop=log.scrollHeight;}
async function beginVaultSetup(password){
  if(!CashflowEncryptedStorage.isPasswordValid(password))throw new Error("Use at least 8 characters, including a letter, a number, and a symbol.");
  const created=await CashflowEncryptedStorage.createVaultSession(state,password);
  vaultEnvelope=created.envelope;
  vaultSession=created.session;
  vaultPendingPassword=password;
  vaultRecoveryPending=created.recoveryKey;
  vaultMode="recovery-confirm";
  vaultError="";
  render();
}
async function copyRecoveryKey(){
  const key=vaultMode==="rotation-confirm"?pendingRotationKey:vaultRecoveryPending;
  let copied=false,copyError=null;
  try{
    if(navigator.clipboard?.writeText){await navigator.clipboard.writeText(key);copied=true;}
  }catch(error){copyError=error;}
  if(!copied){
    let field=null;
    try{
      if(typeof document.execCommand!=="function")throw new Error("Clipboard access is unavailable.");
      field=document.createElement("textarea");
      field.value=key;
      field.setAttribute("readonly","");
      field.style.position="fixed";
      field.style.left="-9999px";
      document.body.append(field);
      field.select();
      copied=document.execCommand("copy");
      if(!copied)throw new Error("The browser did not allow the recovery key to be copied.");
    }catch(error){copyError=error;}
    finally{field?.remove();}
  }
  if(!copied){
    console.error("Could not copy the Cashflow recovery key.",copyError);
    vaultError="Could not copy the key. You can still save it manually and continue.";
    render();
    return;
  }
  vaultMode=vaultMode==="rotation-confirm"?"rotation-verify":"recovery-verify";
  vaultError="";
  render();
  toast("Recovery key copied. Paste it on the next step to confirm.");
}
function continueToRecoveryVerification(){
  vaultMode=vaultMode==="rotation-confirm"?"rotation-verify":"recovery-verify";
  vaultError="";
  render();
}
async function confirmRecoveryKey(value){
  const clean=s=>String(s||"").replace(/[\s-]/g,"").toUpperCase();
  if(clean(value)!==clean(vaultRecoveryPending))throw new Error("That recovery key does not match. Enter it exactly as shown.");
  const verified=await CashflowEncryptedStorage.unlockVault(vaultEnvelope,vaultPendingPassword,"password");
  if(JSON.stringify(verified)!==JSON.stringify(state))throw new Error("The encrypted data could not be verified; your original data has not been removed.");
  const savedEnvelope=await vaultSession.save(state);
  localStorage.setItem(VAULT_KEY,JSON.stringify(savedEnvelope));
  if(migrated)localStorage.removeItem(KEY);
  vaultEnvelope=savedEnvelope;
  vaultPendingPassword="";
  vaultRecoveryPending="";
  vaultMode="open";
  vaultError="";
  render();
  toast("Your ledger is encrypted and saved on this device.");
}
async function unlockLedger(credential,method){
  const unlocked=await CashflowEncryptedStorage.unlockVaultSession(vaultEnvelope,credential,method);
  if(!unlocked.data||typeof unlocked.data!=="object"||!unlocked.data.profile||!unlocked.data.data)throw new Error("The encrypted file does not contain a valid Cashflow ledger.");
  state=normalizeState(unlocked.data);
  coachThread=Array.isArray(state.coachMessages)?state.coachMessages.slice(-40):[];
  vaultSession=unlocked.session;
  vaultMode="open";
  vaultError="";
  try{localStorage.setItem(VAULT_KEY,JSON.stringify(vaultEnvelope));if(localStorage.getItem(KEY)!==null){localStorage.removeItem(KEY);if(localStorage.getItem(KEY)!==null)throw new Error("The old plaintext ledger is still present.");}}catch(e){console.error("Could not finalize local encrypted storage after unlock.",e);vaultMode="error";vaultSession.lock();vaultSession=null;state=fresh();loadError="The encrypted ledger unlocked, but local storage could not be finalized. No ledger is shown. Check browser storage permissions, then reload.";render();return;}
  if(method==="recovery"){vaultMode="recovery-password";vaultError="";render();return;}
  render();
}
async function resetPassword(newPassword){
  await vaultSaveQueue;
  if(vaultSaveError)throw new Error("Fix the encrypted save issue before changing credentials.");
  const next=await vaultSession.preparePasswordChange(newPassword);
  const verified=await CashflowEncryptedStorage.unlockVault(next,newPassword,"password");
  if(JSON.stringify(normalizeState(verified))!==JSON.stringify(state))throw new Error("Password verification failed. The existing credentials are unchanged.");
  localStorage.setItem(VAULT_KEY,JSON.stringify(next));
  vaultSession.adoptEnvelope(next);
  vaultEnvelope=next;
  vaultMode="open";
  vaultError="";
  render();
  toast("Password changed. Your recovery key is unchanged.");
}
async function startRecoveryRotation(){
  await vaultSaveQueue;
  if(vaultSaveError)throw new Error("Fix the encrypted save issue before rotating the recovery key.");
  const next=await vaultSession.prepareRecoveryRotation();
  pendingRotationKey=next.recoveryKey;
  pendingVaultEnvelope=next.envelope;
  vaultMode="rotation-confirm";
  vaultError="";
  render();
}
async function startPasswordReset(){
  await vaultSaveQueue;
  if(vaultSaveError)throw new Error("Fix the encrypted save issue before changing your password.");
  if(vaultSession)vaultSession.lock();
  vaultSession=null;
  state=fresh();
  coachThread=[];
  vaultMethod="recovery";
  vaultMode="unlock";
  vaultError="";
  render();
}
async function confirmRecoveryRotation(value){
  const clean=s=>String(s||"").replace(/[\s-]/g,"").toUpperCase();
  if(clean(value)!==clean(pendingRotationKey))throw new Error("That recovery key does not match. Enter it exactly as shown.");
  const verified=await CashflowEncryptedStorage.unlockVault(pendingVaultEnvelope,pendingRotationKey,"recovery");
  if(JSON.stringify(normalizeState(verified))!==JSON.stringify(state))throw new Error("Recovery-key verification failed. The previous key remains active.");
  localStorage.setItem(VAULT_KEY,JSON.stringify(pendingVaultEnvelope));
  vaultSession.adoptEnvelope(pendingVaultEnvelope);
  vaultEnvelope=pendingVaultEnvelope;
  pendingVaultEnvelope=null;
  pendingRotationKey="";
  vaultMode="open";
  vaultError="";
  render();
  toast("Recovery key replaced. The previous key no longer works.");
}
async function lockLedger(){
  await vaultSaveQueue;
  if(vaultSaveError)throw new Error("The latest changes were not saved securely. Keep the app open and try again.");
  if(vaultSession)vaultSession.lock();
  vaultSession=null;
  state=fresh();
  coachThread=[];
  modal="";
  draft=null;
  vaultMethod="password";
  vaultMode="unlock";
  vaultError="";
  render();
}
function updatePasswordForm(form){
  if(!form)return;
  const password=form.querySelector("[data-password]")?.value||"",confirmation=form.querySelector("[data-password-confirm]")?.value||"";
  const checks={length:password.length>=8,letter:/[A-Za-z]/.test(password),number:/\d/.test(password),symbol:/[^A-Za-z0-9\s]/.test(password),match:password.length>0&&password===confirmation};
  form.querySelectorAll("[data-rule]").forEach(item=>{const valid=checks[item.dataset.rule];item.classList.toggle("valid",valid);item.classList.toggle("invalid",!valid);});
  const button=form.querySelector(".vault-submit");
  if(button)button.disabled=!Object.values(checks).every(Boolean);
}
async function handleVaultSubmit(form){
  const values=Object.fromEntries(new FormData(form));
  if(form.dataset.form==="vault-setup"||form.dataset.form==="vault-migrate"){
    if(values["vault-password"]!==values["vault-confirm"])throw new Error("The passwords do not match.");
    await beginVaultSetup(values["vault-password"]);
    return;
  }
  if(form.dataset.form==="vault-confirm-recovery"){
    await confirmRecoveryKey(values.recoveryConfirm);
    return;
  }
  if(form.dataset.form==="vault-reset-password"){
    if(values["vault-password"]!==values["vault-confirm"])throw new Error("The passwords do not match.");
    await resetPassword(values["vault-password"]);
    return;
  }
  if(form.dataset.form==="vault-confirm-rotation"){
    await confirmRecoveryRotation(values.recoveryConfirm);
    return;
  }
  if(form.dataset.form==="vault-unlock"){
    await unlockLedger(values.password,"password");
    return;
  }
  if(form.dataset.form==="vault-unlock-recovery"){
    await unlockLedger(values.recoveryKey,"recovery");
  }
}
