let t="",f="";if(modal==="account"||modal==="editaccount"){let a=D().accounts.find(x=>x.id===modalId);t=a?"Update account balance":"Add account";f='<div class="formgrid"><div class="field"><label>Name</label><input name="name" value="'+esc(a?.name||"")+'" required></div><div class="field"><label>Type</label><select name="kind">'+opts(["Bank account","Mobile wallet","Cash","Savings account","Business account"],a?.kind||"Bank account")+'</select></div><div class="field"><label>Current balance (NGN)</label><input name="balance" type="number" min="0" value="'+(a?.balance||0)+'" required></div><div class="field"><label>Checked on</label><input name="asof" type="date" value="'+(a?.asof||iso())+'"></div></div>';}
if(modal==="flow"||modal==="editplan"){let plan=D().plans.find(p=>p.id===modalId);t=plan?"Edit planned cashflow":"Plan a cash event";f='<div class="formgrid"><div class="field"><label>Type</label><select name="type">'+opts(["income","expense"],plan?.type||"income")+'</select></div><div class="field"><label>Name</label><input name="name" value="'+esc(plan?.name||"")+'" required placeholder="Salary, client payment, rent"></div><div class="field"><label>Amount</label><input name="amount" type="number" min="1" step="0.01" value="'+(plan?num(plan.amount):"")+'" required></div><div class="field"><label>Date</label><input name="date" type="date" value="'+(plan?.date||shift(7))+'" required></div></div>';}
