if(modal==="editgoal"){let g=D().goals.find(x=>x.id===modalId),cp=Math.max(3,Math.min(6,Math.round(num(g?.checkpoints)||4)));t="Edit goal";f='<div class="formgrid"><div class="field"><label>Goal name</label><input name="name" value="'+esc(g?.name||"")+'" required></div><div class="field"><label>Target ('+goalCurrency(g)+')</label><input name="target" type="number" min="1" value="'+num(g?.target)+'" required></div><div class="field"><label>Deadline (optional)</label><input name="due" type="date" value="'+(g?.due||"")+'"><small>Choose when you want to reach this goal.</small></div><div class="field"><label>Checkpoints</label><select name="checkpoints">'+[3,4,5,6].map(n=>'<option value="'+n+'" '+(n===cp?"selected":"")+'">'+n+' evenly spaced</option>').join("")+'</select><small>Includes the finish at 100%.</small></div></div>';}
if(modal==="contrib-add"||modal==="contrib-subtract"){let g=D().goals.find(x=>x.id===modalId),adding=modal==="contrib-add",saved=num(g?.saved),limit=adding?Math.max(0,num(g?.target)-saved):saved,step=goalCurrency(g)==="USD"?100:1000,amount=Math.min(step,limit)||1,after=adding?Math.min(num(g?.target),saved+amount):Math.max(0,saved-amount);t=adding?"Add contribution":"Subtract contribution";f='<div class="notice">Currently saved: '+goalMoney(g,saved)+'</div><div class="field"><label for="contribution-amount">Amount to '+(adding?"add":"subtract")+' ('+goalCurrency(g)+')</label><div class="amount-stepper"><button type="button" class="stepper" data-action="amount-step" data-step="-1" aria-label="Decrease amount"></button><input id="contribution-amount" name="amount" type="number" min="1" max="'+limit+'" step="'+step+'" value="'+amount+'" data-contribution-amount required><button type="button" class="stepper" data-action="amount-step" data-step="1" aria-label="Increase amount">+</button></div></div><div class="contrib-result"><span>Saved after this change</span><strong data-goal-result>'+goalMoney(g,after)+'</strong></div>';}
