app.addEventListener("submit",e=>{const form=e.target.closest('form[data-form="account"]');if(!form||afterAccountAction!=="import-add-account")return;e.preventDefault();e.stopImmediatePropagation();const values=Object.fromEntries(new FormData(form)),created={id:uid("a"),name:values.name.trim(),kind:values.kind,balance:num(values.balance),asof:values.asof};if(!created.name){toast("Enter an account name.","error");return;}D().accounts.push(created);save();impAccount=created.id;afterAccountAction="";modal="import";render();},true);
