app.addEventListener("click",e=>{let v=e.target.closest("[data-view]");if(v){view=v.dataset.view;search="";render();if(typeof window.scrollTo==="function")window.scrollTo({top:0,behavior:"smooth"});return;}let q=e.target.closest("[data-q]");if(q){sendCoach(q.dataset.q);return;}let b=e.target.closest("[data-action]");if(!b)return;let a=b.dataset.action;if(a==="toggle-secret"){let input=app.querySelector("#"+CSS.escape(b.dataset.target));if(input){let showing=input.type==="password";input.type=showing?"text":"password";b.textContent=showing?"Hide":"Show";b.setAttribute("aria-label",(showing?"Hide ":"Show ")+(input.labels[0]?.textContent||"password").toLowerCase());}return;}if(a==="cancel-rotation"){pendingVaultEnvelope=null;pendingRotationKey="";vaultMode="open";vaultError="";render();return;}if(a==="use-recovery"){vaultMethod="recovery";vaultError="";render();return;}if(a==="start-password-reset"){startPasswordReset().catch(err=>{console.error("Could not start password reset.",err);toast(err.message||"Could not start password reset.","error");});return;}if(a==="rotate-recovery"){startRecoveryRotation().catch(err=>{console.error("Could not rotate recovery key.",err);toast(err.message||"Could not prepare a new recovery key.","error");});return;}if(a==="lock"){lockLedger().catch(err=>{console.error("Could not lock Cashflow.",err);toast("Could not lock safely. Please try again.","error");});return;}if(a==="toggle-balances"){state.profile.hideBalances=!state.profile.hideBalances;save();render();return;}if(a==="theme"){state.profile.theme=state.profile.theme==="dark"?"light":"dark";save();render();return;}if(a==="clear-coach"){coachThread=[];state.coachMessages=[];save();render();return;}if(a==="main-goal"){D().goals.forEach(g=>g.main=g.id===b.dataset.id);save();render();toast("Main goal updated.");return;}if(a==="personal"||a==="business"){switchMode(a);return;}if(a==="close"){modal="";draft=null;afterAccountAction="";render();return;}if(a==="account"){modalForm("account");return;}if(a==="editaccount"){modalForm("editaccount",b.dataset.id);return;}if(a==="flow"){modalForm("flow");return;}if(a==="goal"){if(D().goals.length>=3){toast("You can track up to 3 goals. Remove one before adding another.");return;}modalForm("goal");return;}if(a==="invoice"){modalForm("invoice");return;}if(a==="editgoal"){modalForm("editgoal",b.dataset.id);return;}if(a==="contrib-add"){modalForm("contrib-add",b.dataset.id);return;}if(a==="contrib-subtract"){modalForm("contrib-subtract",b.dataset.id);return;}if(a==="contrib"){modalForm("contrib-add",b.dataset.id);return;}if(a==="amount-step"){let i=b.closest(".amount-stepper")?.querySelector("input");if(i){let low=num(i.min)||1,high=Number(i.max)||Infinity,step=num(i.step)||1000;i.value=Math.max(low,Math.min(high,num(i.value)+(num(b.dataset.step)||0)*step));updateContributionTotal(i);}return;}if(a==="log"){if(!D().accounts.length){modalForm("account");toast("Add an account first.");}else modalForm("tx");return;}if(a==="import"){if(!D().accounts.length){afterAccountAction="import";modalForm("account");toast("Add an account to this ledger first. Your Personal and Business views share the same accounts.");}else{impAccount="";modalForm("import");}return;}if(a==="demo"){demo();return;}if(a==="accept"){let c=0;D().tx.forEach(t=>{if(t.status==="review"&&t.cat!=="Needs sorting"&&t.type!=="transfer"){learn(t,t.cat,t.type);c++;}});save();render();toast(c+" suggestions confirmed.");return;}if(a==="savecat"){let t=D().tx.find(t=>t.id===b.dataset.id),c=app.querySelector('[data-cat="'+b.dataset.id+'"]')?.value,y=app.querySelector('[data-type="'+b.dataset.id+'"]')?.value,p=app.querySelector('[data-purpose="'+b.dataset.id+'"]')?.value;if(t){let matched=learn(t,c||t.cat,y||t.type,p||t.purpose);save();render();toast("Saved. Updated "+matched+" matching merchant row(s); future matches will reuse this feedback.");}return;}if(a==="review-pending"){view="activity";filter="review";render();return;}if(a==="review-purpose-defaults"){view="activity";filter="purpose-default";render();return;}if(a==="paid"){let i=D().invoices.find(i=>i.id===b.dataset.id);if(i){i.status="paid";save();render();toast("Marked paid. Update account balance separately.");}return;}if(a==="delplan"){D().plans=D().plans.filter(p=>p.id!==b.dataset.id);save();render();return;}if(a==="delgoal"){D().goals=D().goals.filter(g=>g.id!==b.dataset.id);normalizeGoals();save();render();return;}if(a==="backup"){download("cashflow-backup-"+iso()+".json",JSON.stringify(state,null,2),"application/json");return;}if(a==="restore"){restore.click();return;}if(a==="csv"){let r=[["date","description","category","purpose","account","type","amount","status"]];D().tx.forEach(t=>r.push([t.date,t.desc,t.cat,t.purpose||"",acct(t.account)?.name||"",t.type,t.amount,t.status]));download("cashflow-activity-"+iso()+".csv",r.map(x=>x.map(csvCell).join(",")).join("\n"),"text/csv");return;}if(a==="reset"&&confirm("Clear all pilot data from this browser?")){localStorage.removeItem(KEY);state=fresh();state.profile.theme="light";coachThread=[];view="home";render();}});
