app.addEventListener("submit",e=>{let f=e.target.closest('form[data-form="import"]');if(!f)return;e.preventDefault();e.stopImmediatePropagation();try{importRows(f);}catch(err){console.error("Statement import could not be completed.",err);toast(err.message||"Could not import this statement.","error");}},true);
app.addEventListener("submit",e=>{let f=e.target.closest("form[data-form]");if(!f)return;e.preventDefault();let type=f.dataset.form;if(type.startsWith("vault-")){handleVaultSubmit(f).catch(err=>{console.error("Cashflow vault action failed.",err);vaultError=err.message||"The encryption step failed. No existing data was removed.";render();});return;}submit(f);});
app.addEventListener("change",e=>{if(e.target.matches("[data-checkpoint-count]")){let g=D().goals.find(g=>g.id===e.target.dataset.id);if(g){g.checkpoints=Math.max(3,Math.min(6,Math.round(num(e.target.value)||4)));save();render();}return;}if(e.target.matches("[data-cadence]")){updateGoalSimulation(e.target);return;}if(e.target.id==="mixedPurposes"){state.profile.mixed=e.target.checked;save();render();return;}if(e.target.id==="statementfile"){let file=e.target.files[0];if(!file)return;if(/\.pdf$/i.test(file.name))readPdf(file);else if(/\.xlsx$/i.test(file.name))readXlsx(file);else if(/\.csv$/i.test(file.name))readCsv(file);else toast("Choose an XLSX, CSV, or PDF statement.","error");return;}if(e.target.matches('[name="account"]')&&modal==="import"){impAccount=e.target.value;let button=app.querySelector('form[data-form="import"] button[type="submit"],form[data-form="import"] .modalfoot button.primary');if(button)button.disabled=!draft||!acct(impAccount);return;}if(e.target.matches("[data-filter]")){filter=e.target.value;render();return;}if(e.target.matches("[data-search]")){search=e.target.value;render();return;}});
app.addEventListener("input",e=>{if(e.target.closest("form[data-form^='vault-setup'],form[data-form='vault-migrate'],form[data-form='vault-reset-password']")){updatePasswordForm(e.target.closest("form"));return;}if(e.target.matches("[data-simulator]")){updateGoalSimulation(e.target);return;}if(e.target.matches("[data-contribution-amount]")){updateContributionTotal(e.target);return;}if(e.target.matches("[data-search]")){search=e.target.value;let p=e.target.selectionStart;render();let x=app.querySelector("[data-search]");x?.focus();x?.setSelectionRange(p,p);}});
restore.addEventListener("change",e=>{let f=e.target.files?.[0];if(!f)return;f.text().then(s=>{let x=JSON.parse(s);if(x&&x.format==="cashflow-encrypted-vault"){if(vaultSession)vaultSession.lock();vaultSession=null;vaultEnvelope=x;state=fresh();vaultMode="unlock";vaultMethod="password";vaultError="";render();return;}if(!x||(!x.workspaces&&!x.data))throw Error("Not a supported Cashflow backup.");state=normalizeState(x);save();render();toast("Backup loaded; it will be encrypted when saved.");}).catch(x=>toast(x.message||"Could not restore.","error")).finally(()=>restore.value="");});
render();